<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>比赛账号与容器绑定</h1><p>比赛账号直接绑定已创建且就绪的比赛槽位。</p></div><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></header><div class="module-table-wrap"><el-table v-loading="loading" :data="accounts" empty-text="暂无比赛账号"><el-table-column prop="userName" label="比赛账号" min-width="160"><template slot-scope="s">{{ s.row.userName || s.row.username || s.row.userId }}</template></el-table-column><el-table-column label="当前绑定" min-width="220"><template slot-scope="s"><span v-if="slotForUser(s.row)">{{ slotLabel(slotForUser(s.row)) }}</span><span v-else class="muted">未绑定，不能进入比赛实操</span></template></el-table-column><el-table-column label="容器状态" width="130"><template slot-scope="s"><el-tag size="small" :type="slotForUser(s.row)?'success':'info'">{{ slotForUser(s.row)?'双容器就绪':'未分配' }}</el-tag></template></el-table-column><el-table-column label="操作" width="190" align="right"><template slot-scope="s"><el-button v-if="slotForUser(s.row)" size="small" type="danger" plain @click="unbind(s.row)">解除绑定</el-button><el-button size="small" type="primary" @click="openBind(s.row)">{{ slotForUser(s.row)?'更换槽位':'绑定槽位' }}</el-button></template></el-table-column></el-table></div><el-dialog title="绑定比赛容器槽位" :visible.sync="dialog" width="520px"><el-form label-width="100px"><el-form-item label="比赛账号">{{ selectedAccount && (selectedAccount.userName || selectedAccount.username || selectedAccount.userId) }}</el-form-item><el-form-item label="可用槽位"><el-select v-model="selectedSlotId" filterable style="width:100%" placeholder="仅显示已创建双容器的 READY 槽位"><el-option v-for="slot in availableSlots" :key="slot.slotId" :label="slotLabel(slot)" :value="slot.slotId" /></el-select><small v-if="!availableSlots.length">暂无可绑定槽位，请先由超级管理员创建比赛容器。</small></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="binding" :disabled="!selectedSlotId" @click="bind">确认绑定</el-button></span></el-dialog></section></template>
<script>
import { adminUsersApi } from '@/api/Match'
import { listCompetitionSlots, bindCompetitionSlot, unbindCompetitionSlot } from '@/api/CompetitionEnvironments'
export default {name:'CompetitionAccounts',data:()=>({loading:false,binding:false,accounts:[],slots:[],dialog:false,selectedAccount:null,selectedSlotId:''}),computed:{availableSlots(){const userId=this.selectedAccount&&this.userId(this.selectedAccount);return this.slots.filter(slot=>slot.slotId&&slot.environmentId&&slot.readiness==='READY'&&(!slot.userId||slot.userId===userId))}},created(){this.load()},methods:{userId(row){return Number(row.userId||row.id)},async load(){this.loading=true;try{const [accounts,slots]=await Promise.all([adminUsersApi(),listCompetitionSlots()]);this.accounts=accounts.data||[];this.slots=slots.data||[]}finally{this.loading=false}},slotForUser(row){const id=this.userId(row);return this.slots.find(slot=>Number(slot.userId)===id)},slotLabel(slot){return `${slot.agentId} / 槽位 ${slot.slotNumber} · ${slot.annotationContainerName} + ${slot.editorContainerName}`},openBind(row){this.selectedAccount=row;const current=this.slotForUser(row);this.selectedSlotId=current&&current.slotId||'';this.dialog=true},async bind(){const id=this.userId(this.selectedAccount);const current=this.slotForUser(this.selectedAccount);this.binding=true;try{if(current&&current.slotId!==this.selectedSlotId)await unbindCompetitionSlot(current.slotId,id);await bindCompetitionSlot(this.selectedSlotId,id);this.$message.success('比赛账号已绑定容器槽位');this.dialog=false;await this.load()}finally{this.binding=false}},async unbind(row){const slot=this.slotForUser(row);await this.$confirm(`确认解除账号与槽位 ${slot.slotNumber} 的绑定？`,'解除绑定',{type:'warning'});await unbindCompetitionSlot(slot.slotId,this.userId(row));await this.load()}}}
</script>
<style scoped>.muted,small{color:var(--ui-muted)}</style>
